// The ready icon components (specs/icon.md, P8): one per drawing of `@ant-design/icons-svg`, generated by
// scripts/generate-icons.mjs, committed, and always equal to what the generator would write now.
import { render } from '@testing-library/svelte';
import { existsSync, readdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import type { Component } from 'svelte';
import { describe, expect, it } from 'vitest';
import { barrelSource, buildIcons, componentSource } from '../scripts/generate-icons.mjs';
import * as data from '../src/lib/Icon/data';
import type { AbstractNode, IconDefinition } from '../src/lib/Icon/types';

const directory = join(import.meta.dirname, '../src/lib/Icon/icons');
const definitions = data as unknown as Record<string, IconDefinition>;
const components = import.meta.glob('../src/lib/Icon/icons/*.svelte', { eager: true, import: 'default' }) as Record<string, Component>;
const countNodes = (node: AbstractNode): number => 1 + (node.children ?? []).reduce((sum, child) => sum + countNodes(child), 0);
const paths = (node: AbstractNode): string[] => [...(node.tag === 'path' ? [node.attrs.d] : []), ...(node.children ?? []).flatMap(paths)];

describe('the generated icon components', () => {
  it('P8: the files on disk are what the generator writes now, and no file is left over', async () => {
    const { files } = await buildIcons();
    expect(readdirSync(directory).sort()).toEqual(Object.keys(files).sort());
    for (const [file, source] of Object.entries(files)) expect(readFileSync(join(directory, file), 'utf8'), file).toBe(source);
  });

  it('P8: every drawing of the installed package has a component, and the barrel exports exactly those', async () => {
    const { names } = await buildIcons();
    expect(names.length).toBeGreaterThan(800);
    const barrel = readFileSync(join(directory, 'index.ts'), 'utf8');
    const exported = [...barrel.matchAll(/export \{ default as (\w+) \} from '\.\/(\w+)\.svelte';/g)];
    expect(exported.map((match) => match[1])).toEqual(names);
    expect(exported.every((match) => match[1] === match[2] && existsSync(join(directory, `${match[2]}.svelte`)))).toBe(true);
    for (const name of ['StarOutlined', 'StarFilled', 'StarTwoTone', 'LoadingOutlined', 'GithubOutlined']) expect(names).toContain(name);
  });

  it('P8: a generated file is a name and an import: it holds no drawing, and says it is generated and from where', () => {
    const source = readFileSync(join(directory, 'StarOutlined.svelte'), 'utf8');
    expect(source).toBe(componentSource('StarOutlined'));
    expect(source).toContain('Generated by scripts/generate-icons.mjs from @ant-design/icons-svg (MIT)');
    expect(source).not.toMatch(/\bd="|"d":/);
    expect(source.length).toBeLessThan(500);
    expect(barrelSource(['A', 'B'])).toContain("export { default as B } from './B.svelte';");
  });

  it('P8: every one of the drawings renders its own drawing through its ready component, with its name', async () => {
    const { names } = await buildIcons();
    const wrongOnes: string[] = [];
    for (const name of names) {
      const component = components[`../src/lib/Icon/icons/${name}.svelte`];
      const definition = definitions[name];
      const { container, unmount } = render(component, {});
      const root = container.querySelector('.ads-icon > svg');
      const root2 = typeof definition.icon === 'function' ? definition.icon('P', 'S') : definition.icon;
      const drawn = [...container.querySelectorAll('.ads-icon > svg path')].map((path) => path.getAttribute('d'));
      const ok =
        root !== null &&
        container.querySelector('.ads-icon')?.getAttribute('aria-label') === definition.name &&
        root.getAttribute('data-icon') === definition.name &&
        JSON.stringify(drawn) === JSON.stringify(paths(root2)) &&
        root.querySelectorAll('*').length === countNodes(root2) - 1;
      if (!ok) wrongOnes.push(name);
      unmount();
    }
    expect(wrongOnes).toEqual([]);
  });

  it('P8: a ready component takes the icon props and no drawing of its own', () => {
    const StarOutlined = components['../src/lib/Icon/icons/StarOutlined.svelte'];
    const { container } = render(StarOutlined, { spin: true, rotate: 90, label: 'Favourite', class: 'mine' } as never);
    const wrapper = container.querySelector('.ads-icon')!;
    expect(wrapper.getAttribute('aria-label')).toBe('Favourite');
    expect(wrapper.classList.contains('ads-icon-spin')).toBe(true);
    expect(wrapper.classList.contains('mine')).toBe(true);
  });

  it('P8: the three themes of a drawing are three components: the outlined, the filled and the two-tone one differ', () => {
    const shapes = ['StarOutlined', 'StarFilled', 'StarTwoTone'].map((name) => {
      const { container, unmount } = render(components[`../src/lib/Icon/icons/${name}.svelte`], {});
      const shape = [...container.querySelectorAll('path')].map((path) => path.getAttribute('d')).join('|');
      unmount();
      return shape;
    });
    expect(new Set(shapes).size).toBe(3);
  });
});
